// Rows of the previous calendar month, oldest first, ready for the tax advisor.
const from = $now.minus({ months: 1 }).startOf('month').toFormat('yyyy-MM-dd');
const to = $now.startOf('month').toFormat('yyyy-MM-dd');
const cols = ['invoiceDate', 'invoiceNumber', 'sellerName', 'sellerVatId', 'currency', 'netAmount', 'vatAmount',
  'grossAmount', 'amountDue', 'dueDate', 'iban', 'status', 'source', 'format', 'fileName', 'problems'];
const dec = v => (v === null || v === undefined || v === '' ? '' : Number(v).toFixed(2).replace('.', ','));
return $input.all()
  .map(i => i.json)
  .filter(r => r.invoiceDate >= from && r.invoiceDate < to)
  .sort((a, b) => a.invoiceDate.localeCompare(b.invoiceDate))
  .map(r => ({ json: Object.fromEntries(cols.map(c => [c, /Amount$/.test(c) ? dec(r[c]) : (r[c] ?? '')])) }));
